<?php require_once '../../config/conexion.php'; $fecha=$_POST['fecha']??date('Y-m-d');$cliente=trim($_POST['cliente']??'');$producto=$_POST['producto']??'';$cantidad=(float)$_POST['cantidad'];$precio=(float)$_POST['precio'];$total=$cantidad*$precio;$s=$conn->prepare('INSERT INTO ventas (fecha,cliente,producto,cantidad_m3,precio_m3,total) VALUES (?,?,?,?,?,?)');$s->bind_param('sssddd',$fecha,$cliente,$producto,$cantidad,$precio,$total);$s->execute();header('Location: index.php');exit;
